import{_ as s,o as r,c as t,ai as i}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Créer des suites de benchmark personnalisées","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/benchmark-builder.md","filePath":"fr/guide/benchmark-builder.md"}'),o={name:"fr/guide/benchmark-builder.md"};function n(l,e,u,a,d,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="creer-des-suites-de-benchmark-personnalisees" tabindex="-1">Créer des suites de benchmark personnalisées <a class="header-anchor" href="#creer-des-suites-de-benchmark-personnalisees" aria-label="Permalink to &quot;Créer des suites de benchmark personnalisées&quot;">​</a></h1><p>Créez vos propres suites de benchmark pour tester les modèles sur les sujets qui comptent pour vous — aucune modification de JSON requise. Le constructeur de suites de benchmark vous permet de rédiger des questions manuellement ou d&#39;utiliser un modèle IA local pour les générer automatiquement.</p><p><strong>Élément de la barre latérale :</strong> Constructeur de Benchmark <strong>Route :</strong> <code>/benchmark</code> (onglet Constructeur)</p><h2 id="saisie-manuelle-de-questions" tabindex="-1">Saisie manuelle de questions <a class="header-anchor" href="#saisie-manuelle-de-questions" aria-label="Permalink to &quot;Saisie manuelle de questions&quot;">​</a></h2><p>Pour construire une suite entièrement à la main :</p><ol><li>Ouvrez la page <strong>Benchmark</strong> et cliquez sur l&#39;onglet <strong>Constructeur</strong>.</li><li>Entrez un <strong>nom de suite</strong> et une <strong>description</strong> optionnelle.</li><li>Cliquez sur <strong>Ajouter une question</strong> pour créer une nouvelle entrée.</li><li>Remplissez le <strong>texte de la question</strong>.</li><li>Ajoutez les <strong>choix de réponses</strong> (A, B, C, D). Vous pouvez ajouter plus de choix si nécessaire.</li><li>Sélectionnez la <strong>bonne réponse</strong> dans le menu déroulant.</li><li>Attribuez éventuellement une <strong>catégorie</strong> pour regrouper les questions par sujet.</li><li>Répétez les étapes 3 à 7 pour chaque question que vous souhaitez ajouter.</li><li>Cliquez sur <strong>Enregistrer la suite</strong> lorsque vous avez terminé.</li></ol><p>Votre suite personnalisée apparaît désormais aux côtés des suites intégrées et est prête à être exécutée.</p><h2 id="generation-assistee-par-ia" tabindex="-1">Génération assistée par IA <a class="header-anchor" href="#generation-assistee-par-ia" aria-label="Permalink to &quot;Génération assistée par IA&quot;">​</a></h2><p>Laissez un modèle local faire le gros du travail :</p><ol><li>Dans l&#39;onglet Constructeur, basculez vers la section <strong>Génération IA</strong>.</li><li>Entrez un <strong>sujet</strong> — par exemple, &quot;Révolution française&quot;, &quot;Réseaux TCP/IP&quot; ou &quot;Chimie organique&quot;.</li><li>Choisissez le <strong>nombre de questions</strong> à générer.</li><li>Sélectionnez un niveau de <strong>difficulté</strong> (facile, moyen, difficile).</li><li>Choisissez le <strong>modèle</strong> qui générera les questions dans le menu déroulant.</li><li>Cliquez sur <strong>Générer</strong>. Le modèle diffuse les questions en temps réel.</li></ol><p>Une fois la génération terminée :</p><ul><li><strong>Relisez</strong> chaque question pour vérifier sa précision.</li><li><strong>Modifiez</strong> le texte, les choix ou les bonnes réponses qui nécessitent des corrections.</li><li><strong>Désélectionnez</strong> les questions mal formulées ou incorrectes — elles ne seront pas incluses.</li><li>Cliquez sur <strong>Ajouter à la suite</strong> pour intégrer les questions approuvées dans votre suite.</li></ul><h2 id="modifier-les-suites" tabindex="-1">Modifier les suites <a class="header-anchor" href="#modifier-les-suites" aria-label="Permalink to &quot;Modifier les suites&quot;">​</a></h2><p>Cliquez sur le bouton <strong>Modifier</strong> sur n&#39;importe quelle suite personnalisée pour la modifier. Vous pouvez :</p><ul><li>Renommer la suite ou mettre à jour sa description</li><li>Ajouter, supprimer ou réorganiser les questions</li><li>Modifier le texte, les choix et les bonnes réponses de chaque question</li><li>Changer les catégories des questions</li></ul><p>Les suites intégrées (ARC, GSM8K, etc.) ne peuvent pas être modifiées, mais vous pouvez les dupliquer pour en créer une version modifiée.</p><h2 id="exporter" tabindex="-1">Exporter <a class="header-anchor" href="#exporter" aria-label="Permalink to &quot;Exporter&quot;">​</a></h2><p>Cliquez sur le bouton <strong>Exporter</strong> sur une suite personnalisée pour la télécharger en fichier <strong>JSON</strong>. Le fichier exporté contient :</p><ul><li>Le nom et la description de la suite</li><li>Toutes les questions avec leurs choix, l&#39;index de la bonne réponse et la catégorie</li></ul><p>Partagez les fichiers JSON exportés avec d&#39;autres ou contribuez-les à la collection de <a href="/llmxray/docs/fr/community/benchmarks.html">Benchmarks Communautaires</a>.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Utilisez des sujets spécifiques</strong> — &quot;Chaîne de transport d&#39;électrons mitochondriale&quot; génère de meilleures questions que &quot;biologie&quot;. Plus le sujet est ciblé, plus le résultat de l&#39;IA est précis.</li><li><strong>Combinez manuel et IA</strong> — Générez un lot avec l&#39;IA, puis ajoutez quelques questions rédigées à la main pour couvrir les cas limites.</li><li><strong>Validez toujours les réponses</strong> — Les bonnes réponses générées par l&#39;IA peuvent être fausses. Vérifiez chacune d&#39;entre elles avant d&#39;enregistrer.</li><li><strong>Les modèles plus grands produisent de meilleures questions</strong> — Un modèle de 14 milliards de paramètres génère des questions nettement plus précises et nuancées qu&#39;un modèle de 3 milliards. Utilisez le meilleur modèle dont vous disposez.</li><li><strong>Catégorisez de manière cohérente</strong> — Utilisez des noms de catégories cohérents entre les questions pour que le détail des résultats soit pertinent.</li><li><strong>Commencez petit</strong> — Générez 5 à 10 questions d&#39;abord pour vérifier la qualité avant de vous lancer dans un lot plus important.</li></ul>',22)])])}const g=s(o,[["render",n]]);export{m as __pageData,g as default};
